package dev.rodrigosambade.oca;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.random.RandomGenerator;
public final class GameServer implements AutoCloseable{private final ServerSocket server;private final int expected;private final List<Player>players=new ArrayList<>();private volatile boolean closed;private final GooseGame game=new GooseGame();private final RandomGenerator random=RandomGenerator.getDefault();private static final class Player{final Socket socket;final BufferedReader in;final BufferedWriter out;final String nick;int pos,skip;Player(Socket s)throws IOException{socket=s;in=new BufferedReader(new InputStreamReader(s.getInputStream(),StandardCharsets.UTF_8));out=new BufferedWriter(new OutputStreamWriter(s.getOutputStream(),StandardCharsets.UTF_8));String n=in.readLine();if(n==null||n.isBlank())throw new IOException("nick required");nick=n.trim();}void send(String x)throws IOException{out.write(x);out.newLine();out.flush();}}public GameServer(int port,int expected)throws IOException{if(expected<2)throw new IllegalArgumentException();this.expected=expected;server=new ServerSocket(port);}public int port(){return server.getLocalPort();}public void run()throws IOException{while(players.size()<expected){Socket s=server.accept();try{Player p=new Player(s);if(players.stream().anyMatch(x->x.nick.equalsIgnoreCase(p.nick))){p.send("ERROR|duplicate nick");s.close();continue;}players.add(p);p.send("WELCOME|"+(players.size()-1));broadcast("JOIN|"+p.nick);}catch(IOException e){s.close();}}broadcast("PLAYERS|"+String.join(",",players.stream().map(p->p.nick).toList()));int turn=0;while(!closed){Player p=players.get(turn);if(p.skip>0){p.skip--;broadcast("SKIP|"+p.nick+"|"+p.skip);turn=(turn+1)%players.size();continue;}p.send("TURN");String cmd=p.in.readLine();if(cmd==null){broadcast("LEAVE|"+p.nick);return;}if(!cmd.equals("ROLL")){p.send("ERROR|expected ROLL");continue;}int roll=random.nextInt(1,7);var move=game.apply(p.pos,roll);p.pos=move.to();p.skip=move.skipTurns();broadcast("MOVE|"+p.nick+"|"+roll+"|"+move.to()+"|"+move.message());if(move.won()){broadcast("WIN|"+p.nick);return;}if(!move.extraTurn())turn=(turn+1)%players.size();}}private void broadcast(String m)throws IOException{for(Player p:players)p.send(m);}@Override public void close()throws IOException{closed=true;for(Player p:players)try{p.socket.close();}catch(IOException ignored){}server.close();}public static void main(String[]a)throws Exception{int port=a.length>0?Integer.parseInt(a[0]):5000,n=a.length>1?Integer.parseInt(a[1]):2;try(var s=new GameServer(port,n)){s.run();}}}
